  rows.push({ siteId: site.id, pageSlug: "emerald-forest", sectionKey: "policies", order: 0, content: { cancellationPolicy: "Fifty percent (50.00%) of the total booking charges will be refunded if the cancellation is made more than 30 days prior to the arrival date of the reservation. For cancellations made within 30 days prior to the arrival date, no refund will be issued.", notes: ["Like many mountain cabins, Emerald Forest is accessed by a gravel mountain road with a steep section. During winter weather, 4WD or snow chains are needed for safe access.", "Parties & events are not permitted", "The house is non-smoking", "The cabin is pet-friendly with prior host approval & a pet fee. We require that pets be crated if left unattended at the cabin during your stay.", "There is one outside security camera that captures the driveway.", "Construction in the Smoky Mountains may occasionally be audible.", "We provide a DVD Player for movies, and a Roku TV."], houseRules: ["Maximum occupancy: 2", "Children welcome", "Infants welcome", "Smoking not allowed", "Wheelchair inaccessible", "Minimum age of primary renter: 18", "Pets welcome"], expectations: ["Requires Stairs (Approximately 10 stairs onto the deck)", "Limited Parking", "Cameras/Surveillance (One security camera that monitors the driveway/parking area)", "Pool/Jacuzzi With No Fence (Hot tub located on back deck)"] } });
