  rows.push({ siteId: site.id, pageSlug: "golden-forest", sectionKey: "basics", order: 0, content: { name: "Golden Forest", tagline: "Warmth & Glow", description: "Golden details, a king Stearns & Foster bed, fireside double Jacuzzi, private hot tub and a deck wrapping around three sides of the cabin.", image: "https://admin.weblaucher.com/api/media/sites/6d8fcbd5-beb3-465d-9e55-d6da1ae3ef42/seed/just-opened.jpg", highlights: ["Private hot tub", "Fireside double Jacuzzi", "Three-sided deck"], badgeLabel: "Just Opened", size: "Studio", baths: 1, sleeps: 2, categoryLabel: "Secluded forest" } });
  rows.push({ siteId: site.id, pageSlug: "golden-forest", sectionKey: "detail", order: 0, content: { headline: "Golden Hours. Quiet Mornings. Just the Two of You.", subtitle: "Romantic studio for two · Private hot tub · Double Jacuzzi · Three-sided deck", story: ["Golden Forest brings warmth and glow to our Hidden Gem Cabin Series.", "Inside, golden details and thoughtfully selected finishes surround a king Stearns & Foster bed, fireside double Jacuzzi, gas fireplace with carved bear mantle and fully equipped kitchen.", "Outside, the deck wraps around three sides of the cabin, giving you different views of the forest as the light changes throughout the day. Your private hot tub waits beneath the trees.", "Fall may put on the most obvious golden show, but summer greenery, winter evenings by the fire and fresh spring mornings make this a retreat for every season."], highlights: ["King Stearns & Foster Bed", "Fireside Double Jacuzzi", "Private Hot Tub", "Three-Sided Wrap-Around Deck", "Gas Fireplace + Carved Bear Mantle", "Full Kitchen"] } });
