  rows.push({ siteId: site.id, pageSlug: "ladyslipper", sectionKey: "basics", order: 0, content: { name: "Ladyslipper", tagline: "A Storybook A-Frame", description: "Seven wooded acres, a king bed, real wood-burning fireplace, double Jacuzzi, wrap-around porch and private hot tub—all within five miles of Gatlinburg and Pigeon Forge.", image: "https://admin.weblaucher.com/api/media/sites/6d8fcbd5-beb3-465d-9e55-d6da1ae3ef42/seed/ladyslipper.jpg", highlights: ["Private hot tub", "Seven wooded acres", "Wood-burning fireplace"], badgeLabel: "A-Frame", size: "Studio A-Frame", baths: 1, sleeps: 2, categoryLabel: "Secluded forest" } });
  rows.push({ siteId: site.id, pageSlug: "ladyslipper", sectionKey: "detail", order: 0, content: { headline: "A Storybook A-Frame Hidden in the Woods", subtitle: "Romantic cabin for two · Seven wooded acres · Private hot tub · Wood-burning fireplace", story: ["Ladyslipper gives you the classic Smoky Mountain cabin experience: an intimate A-frame tucked among seven wooded acres, yet within five miles of both Gatlinburg and Pigeon Forge.", "Inside, settle into the king-size bed, build a fire in the real wood-burning fireplace, or soak together in the double Jacuzzi. A full kitchen makes breakfast in pajamas or dinner at the cabin easy.", "Outside, a wrap-around porch, porch swing and private hot tub invite you to slow down and enjoy the forest. Soft robes, cozy blankets and a classic radio add to the feeling that there's really no reason to rush anywhere."], highlights: ["Classic A-Frame", "Seven Wooded Acres", "King Bed", "Real Wood-Burning Fireplace", "Double Jacuzzi", "Private Hot Tub", "Wrap-Around Porch + Porch Swing", "Full Kitchen"] } });
