  rows.push({ siteId: site.id, pageSlug: "ladyslipper", sectionKey: "photos", order: 0, content: { items: ["https://uc.orez.io/i/1439bed1d67744cd8ce5e610aa0c2f0e-Large", "https://uc.orez.io/i/f13a141308754abd846b6984964c03da-Large", "https://uc.orez.io/i/7ac483de0cf84cb0831619aa83a37c74-Medium", "https://uc.orez.io/i/c4415b011597436dbcbade2f09ed82fb-Large", "https://uc.orez.io/i/54ebf4f1b34046db827b0194ca87f5bc-Large", "https://uc.orez.io/i/966a39a9a7364694a8e6285b5c5c4540-Large", "https://uc.orez.io/i/0f34625fe36246a6a550341c7ad6ec8a-Large", "https://uc.orez.io/i/fe4fbe3c2d2e452d9a895105c5b0e5e8-Large", "https://uc.orez.io/i/ac0e4075efa84878a8b0c9e0905f0534-Large", "https://uc.orez.io/i/62577de1b42949b7abe83a2203ba6dfa-Large", "https://uc.orez.io/i/f8abd777519f4f4d9967c59e6fc1d92f-Large", "https://uc.orez.io/i/453b85bae01b4ca6bbda9b5410c2c4e9-Large", "https://uc.orez.io/i/c6888df1b7fe4e7ebc453b716d125657-Large", "https://uc.orez.io/i/090ab310b0294be2b1d65de69493e1c6-Large", "https://uc.orez.io/i/d04799f0cffd412c9274519d183f3c48-Large", "https://uc.orez.io/i/78d2787b09234cd49d4198b2962f13ed-Large", "https://uc.orez.io/i/1ea121086dad44bfb6efb56e4885254a-Large", "https://uc.orez.io/i/fa920e6645354992b0813baf08291be9-Large", "https://uc.orez.io/i/5edeb313deef49f1982ec564ae120619-Large", "https://uc.orez.io/i/d5529670eea04a3b8530c941b53cfdbb-Large", "https://uc.orez.io/i/7cc887f910d6457293329ec5f5c9a563-Large", "https://uc.orez.io/i/d040239b67684d92ad08332d528a6d29-Large", "https://uc.orez.io/i/c0c86ff1f52a4988aabac7f0a22b5f24-Large", "https://uc.orez.io/i/93f5004061304a679d341432a79310da-Large", "https://uc.orez.io/i/4be85dee9e4d42c88b4459981bf09b9f-Large", "https://uc.orez.io/i/b7eb65e3f30647feabc883a01ecb1ea0-Large", "https://uc.orez.io/i/63041cfc3e7440f88a159be7f81aad93-Large", "https://uc.orez.io/i/cc3ac30131cd4e919b9b3acbd21d62f5-Large", "https://uc.orez.io/i/21f78da760e54620a0a7e5b3f453b71e-Large", "https://uc.orez.io/i/aa956f7d536f40eda9e1b06d4c56a183-Large"] } });
  rows.push({ siteId: site.id, pageSlug: "ladyslipper", sectionKey: "description", order: 0, content: { blocks: [{ type: "p", text: "The cozy  Lady Slipper cabin is designed with romance in mind while still being conveniently within 5 miles of Pigeon Forge, Gatlinburg & all the area's top attractions." }, { type: "h", text: "Living Spaces" }, { type: "p", text: "When you walk up the few stairs to the large wrap-around porch you will enter the studio cabin through gorgeous, double glass doors & be welcomed into your intimate cabin getaway. A king- size bed is situated in the middle of the cabin with a Smart TV mounted on the wall parallel allowing you to cuddle up with your sweetheart to watch a movie or your favorite show." }, { type: "p", text: "A grand wood-burning fireplace is the centerpiece of the cabin with lots of cozy seating & pillows placed nearby at the foot of the bed. Curl up with one of the blankets or wrap up in a luxurious robe & enjoy each other's company. Turn on the classic radio located on the mantel & relax or slow dance for a while." }, { type: "p", text: "A double Jacuzzi, with a curtain and shower head available, is conveniently located nearby so that you can soak fireside." }, { type: "h", text: "Kitchen & Dining" }, { type: "p", text: "The studio cabin space also features a fully equipped kitchen with an electric stove, oven, microwave, fridge, & coffee pot. Alongside all basic appliances, the cabin has cookware, dishes, glasses & utensils to cook & enjoy any meal together. A bistro table & chairs are located right off the kitchen so that you can enjoy a romantic fireside meal." }, { type: "h", text: "Bedrooms & Baths" }, { type: "p", text: "The tub & shower are located within the studio cabin area to elevate your romantic experience at Lady Slipper. The bathroom with a toilet & sink has its own private space with a door. Hotel-quality towels & linens are provided during your stay." }, { type: "h", text: "Outdoor Amenities" }, { type: "p", text: "Enjoy each other's company amongst nature with rocking chairs and a swinging porch bench right out the front door. Enjoy a nice cup of coffee in the morning looking out to the 7 acres of forest surrounding the cabin while listening to the bird's sing." }, { type: "p", text: "If you would like to make dinner easy, grill up something on the charcoal grill, step outside the cabin & enjoy your meal al fresco at the dining table on the patio." }, { type: "p", text: "Your storybook, romantic getaway awaits, & we look forward to welcoming you to the Lady Slipper cabin!" }, { type: "p", text: "You will feel as if you are in the middle of the forest in the Sky Harbor community while only being 5 miles from both Pigeon Forge & Gatlinburg. Relax in your secluded, private cabin & enjoy easy access to the area's many attractions:" }, { type: "li", text: "15 min to Dollywood" }, { type: "li", text: "10-15 min Gatlinburg" }, { type: "li", text: "10-15 min Pigeon Forge" }, { type: "p", text: "The area offers activities for every budget & desired adventure level to choose from! Please feel free to ask us if you would like any personalized recommendations on activities, we would be happy to help you create an unforgettable trip!" }, { type: "p", text: "Hiking; nearby the cabin & in The Great Smoky Mountain National Park" }, { type: "li", text: "White Water Rafting" }, { type: "li", text: "Swimming" }, { type: "li", text: "Fishing" }, { type: "li", text: "Horseback Riding" }, { type: "li", text: "Shopping" }, { type: "li", text: "Arts & Crafts" }, { type: "li", text: "Theater Dinners" }, { type: "li", text: "Restaurants" }, { type: "p", text: "And More!" }, { type: "p", text: "Lady Slipper is located up in the mountains with some incline & curvy roads. During normal conditions it is accessible with any vehicle, however; during the winter months or during inclement weather with ice/snow, 4WD and/or snow chains are necessary to access the cabin." }, { type: "p", text: "The closest airport is:" }, { type: "h", text: "TYS (Knoxville, TN) - approximately 1 hour away" }, { type: "p", text: "AVL (Asheville, NC) - approximately 1.5 hours away" }] } });
