  rows.push({ siteId: site.id, pageSlug: "wild-columbine", sectionKey: "basics", order: 0, content: { name: "Wild Columbine", tagline: "Secluded, Yet Close to It All", description: "A romantic forest cabin for two with a king bed, wood-burning fireplace, double Jacuzzi, wrap-around porch and private hot tub.", image: "https://admin.weblaucher.com/api/media/sites/6d8fcbd5-beb3-465d-9e55-d6da1ae3ef42/seed/wild-columbine.jpg", highlights: ["Private hot tub", "Double Jacuzzi", "Wood-burning fireplace"], badgeLabel: "", size: "Studio", baths: 1, sleeps: 2, categoryLabel: "Secluded forest" } });
  rows.push({ siteId: site.id, pageSlug: "wild-columbine", sectionKey: "detail", order: 0, content: { headline: "Feel Miles From Everything. Be Minutes From Both Towns.", subtitle: "Romantic forest cabin for two · Private hot tub · Wood-burning fireplace · Double Jacuzzi", story: ["Wild Columbine is for couples who want the woods to actually feel like the woods.", "This intimate cabin surrounds you with the Smoky Mountain forest while keeping Gatlinburg and Pigeon Forge close enough for dinner, attractions and days exploring the National Park.", "Inside, a king-size bed, real wood-burning fireplace, double Jacuzzi and equipped kitchen make staying in just as appealing as going out.", "Outside, the wrap-around porch and private hot tub beneath the trees give you a place to slow down and listen to the forest. Spend the day doing everything—or decide to do absolutely nothing."], highlights: ["King Bed", "Real Wood-Burning Fireplace", "Double Jacuzzi", "Private Hot Tub", "Wrap-Around Porch", "Equipped Kitchen", "Forest Setting"] } });
  rows.push({ siteId: site.id, pageSlug: "wild-columbine", sectionKey: "nearby", order: 0, content: { items: [{ place: "Gatlinburg", time: "5 mi" }, { place: "Pigeon Forge", time: "5 mi" }, { place: "Knoxville airport (TYS)", time: "~1 hr" }] } });
