  rows.push({ siteId: site.id, pageSlug: "wild-columbine", sectionKey: "description", order: 0, content: { blocks: [{ type: "p", text: "Tucked away in the forest, you will find our perfectly romantic cabin named Wild Columbine filled with rustic charm. Enjoy seclusion in your private hottub and reconnect with one another and with nature. Although you will feel far away fro the world, our cabin is close to everything! Just 5 miles in to both Gatlinburg and Pigeon Forge." }, { type: "li", text: "King-size bed" }, { type: "li", text: "Double Jacuzzi Inside" }, { type: "li", text: "Wood Burning Fireplace" }, { type: "li", text: "Fully Equipped Kitchen" }, { type: "li", text: "BBQ Grill" }, { type: "li", text: "Hottub on your back deck" }, { type: "p", text: "You will find a Hot tub on the deck, and a beautiful wrap around porch for sunbathing or watching the forest and connecting with nature. Inside a king bed, double jacuzzi and wood burning fireplace is a perfect place to connect with each other." }, { type: "p", text: "Our space also has a full kitchen, as well as a charcoal grill outside. Gatlinburg and Pigeon Forge offer hundreds of things to do such as:" }, { type: "li", text: "Restaurants" }, { type: "li", text: "Shopping" }, { type: "li", text: "Attractions" }, { type: "li", text: "Dinner theaters" }, { type: "p", text: "and more!" }, { type: "p", text: "We are just miles from the Great Smoky Mountains National Park." }, { type: "li", text: "Hiking" }, { type: "li", text: "Swimming" }, { type: "li", text: "Fishing" }, { type: "li", text: "Horseback riding" }, { type: "li", text: "Wildlife watching" }, { type: "li", text: "Whitewater rafting" }, { type: "li", text: "Skiing" }, { type: "li", text: "Zip lining" }, { type: "p", text: "are all activities that you can find close by." }, { type: "p", text: "We are so excited for you to experience this special place we love so much!" }, { type: "p", text: "You will access the cabin via lockbox and self check in." }, { type: "p", text: "Our cabin has a gravel driveway with an incline, and during the winter months when snow/ice is possible we strongly suggest a 4WD vehicle." }] } });
