  rows.push({ siteId: site.id, pageSlug: "firefly-bungalow-2", sectionKey: "basics", order: 0, content: { name: "Firefly Bungalow #2", tagline: "Stay Close to the Fun", description: "A one-story Pigeon Forge bungalow with family-friendly comforts and a private hot tub, steps from the Parkway.", image: "https://admin.weblaucher.com/api/media/sites/6d8fcbd5-beb3-465d-9e55-d6da1ae3ef42/seed/steps-from-parkway.jpg", highlights: ["Private hot tub", "One-story layout", "Family games"], badgeLabel: "Sleeps 6", size: "2 Bedrooms", baths: 1, sleeps: 6, categoryLabel: "Walk to the Parkway" } });
  rows.push({ siteId: site.id, pageSlug: "firefly-bungalow-2", sectionKey: "detail", order: 0, content: { headline: "Your Own Place, Steps From the Parkway", subtitle: "In-town Pigeon Forge · Private hot tub · Family-friendly · One-story", story: ["Firefly Bungalow #2 combines the convenience of an in-town Pigeon Forge stay with the comfort of having a place of your own.", "The one-story bungalow features reclaimed barn-wood walls, family games, television, an electric wood stove and flexible sleeping space. Two AC units and supplemental space heaters help keep the bungalow comfortable through changing seasons.", "Best of all, you're steps from the Pigeon Forge Parkway and have your own private hot tub waiting after Dollywood, hiking, sightseeing or a full day of attractions."], highlights: ["Steps From the Parkway", "Private Hot Tub", "One-Story Layout", "Family Games", "Reclaimed Barn-Wood Character", "Flexible Sleeping Space", "Electric Wood Stove"] } });
