  rows.push({ siteId: site.id, pageSlug: "firefly-bungalow-2", sectionKey: "photos", order: 0, content: { items: ["https://uc.orez.io/i/3e00899292e74e03863d62451713667e-Large", "https://uc.orez.io/i/d2ecda07d85844d397c4d07303418f63-Large", "https://uc.orez.io/i/f571c58761d74e1abe35389c06d5494d-Large", "https://uc.orez.io/i/c5c496b808444c0ebb8305a0c42d085b-Large", "https://uc.orez.io/i/8df8006ba89047058223f40a1b0a0e3f-Large", "https://uc.orez.io/i/c39f767341b547e0a43478459d2ba05d-Large", "https://uc.orez.io/i/592a82ae278941b384ee54c58f8fd17e-Large", "https://uc.orez.io/i/b03d61acf72f43c2b59c6a6b62cf0127-Large", "https://uc.orez.io/i/9b2ff57fddc54d50bfbeab4d0e93963c-Large", "https://uc.orez.io/i/f8fe07d7c3d04a549b1856cd279d3af8-Large", "https://uc.orez.io/i/07e473e0191f4ec2bc46b3f9e5832978-Large", "https://uc.orez.io/i/ef65abdb301546c9973a396c49f18476-Large", "https://uc.orez.io/i/3279ed7751d24aacadea8f936398a50a-Large", "https://uc.orez.io/i/0a926a6c9b1f4ac6845c50918719f1e4-Large", "https://uc.orez.io/i/eaa49b1321594edbb1e1b9f5b4ed34cb-Large", "https://uc.orez.io/i/ff58b03ee0ac4b22a2e9128737e565e6-Large", "https://uc.orez.io/i/8108f428139e428189d4334f09d2f12b-Large", "https://uc.orez.io/i/71c12e355d9f4ba2a3c39467c48760cb-Large", "https://uc.orez.io/i/a71af58f5d634679847735b9c7334403-Large", "https://uc.orez.io/i/72b41b82788046f9b3aa18af2ba946f4-Large", "https://uc.orez.io/i/640b9482bf2e41518cb702a52e0e5c6c-Large", "https://uc.orez.io/i/0fae797c14314801a40d9b81ce3e3f2d-Large", "https://uc.orez.io/i/160359a3470a468b89bba26df2223396-Large", "https://uc.orez.io/i/8767695e99ea47d890277b2a9266e5c8-Large", "https://uc.orez.io/i/fc9b03f220214ae99b92be8f8dc35157-Large", "https://uc.orez.io/i/1309a5bc6b134aae984a7bd3d4019823-Large", "https://uc.orez.io/i/f8cd9a5683504596b88b0dd298de46b0-Large", "https://uc.orez.io/i/196fcfc20d9a4ab2af733a2c6281ddbc-Large", "https://uc.orez.io/i/1265d73a473243fe92ae56e0de5a9a2e-Large", "https://uc.orez.io/i/a4ba9e2accf3440890e651218a5cdc1d-Large", "https://uc.orez.io/i/8e85c474e1624b5d824020abb9e51bc8-Large", "https://uc.orez.io/i/b38a11c8eff94a3cb653edcda1619cb7-Large", "https://uc.orez.io/i/75989b4b27d14e5e8236c68ec947ec35-Large"] } });
  rows.push({ siteId: site.id, pageSlug: "firefly-bungalow-2", sectionKey: "description", order: 0, content: { blocks: [{ type: "p", text: "Here at Firefly Bungalow #2, the music of crickets, peepers, and whippoorwills will lull you to sleep. The faint fragrance of mountain magnolia will greet you in springtime. Flashes of fireflies, and rhythms of rain on the metal roof will delight you on summer evenings. Autumn foliage will lure the leaf peepers. Fresh winter snowfall on mountain peaks is breathtaking, and holiday events in the Smokies draw travelers from around the world. Firefly Bungalow #2 is perfect for couples, families, and small groups of friends." }, { type: "h", text: "Living Spaces" }, { type: "p", text: "The living room has accent walls of reclaimed barn wood, a ceiling fan, a sturdy oak futon/sofa-bed, a coffee table, an electric wood stove/fireplace-style heater, and a large wall-mounted flat-screen TV. After a day exploring the mountains, curl up in the evenings and stream your favorite movies or shows. There’s also a vintage trunk with a variety of family games." }, { type: "p", text: "This one-story bungalow has two AC units for cooling in the summer, and space heaters throughout for heating in winter. It is tranquil in all seasons. The wood, wooden furnishings, and old-time Appalachian decor give this cabin-style home a rustic, Smoky Mountain ambiance." }, { type: "h", text: "Kitchen & Dining" }, { type: "p", text: "The kitchen has solid wood cabinets and natural pinewood trim. Appliances include a four-burner electric range, oven, microwave, Keurig coffee maker, toaster, large double-basin stainless steel sink, and French door fridge/freezer combo. Gorgeous, natural edge, wooden, open shelving nicely displays dishware, glassware, and stemware. A decorative lantern chandelier adds charm and character to the kitchen. The dining area offers a sturdy, solid wood, Amish-style circular table with seating for four." }, { type: "h", text: "Bedrooms & Baths" }, { type: "p", text: "Firefly Bungalow #2 has two bedrooms, each with a luxurious king-size bed, authentic quilts, nightstands with reading lamps, closets with built-in chest of drawers, and wall mount, flat-screen TVs. (For guests traveling with small children, a pack and play is available upon request.) The two king bedrooms share access to a full bathroom off the hallway, with a tub/shower combo, single-sink vanity, large well-lit mirror, and plenty of cabinet storage space. Toiletries, hairdryer, robes, and plush towels are all provided." }, { type: "h", text: "Outdoor Amenities" }, { type: "p", text: "Nicely landscaped outdoor areas truly set this bungalow apart. Indulge in the hot tub after a day of outdoor Smoky Mountain adventure or gather around the firepit for s’mores. The backyard offers a picnic table for outdoor dining, a BBQ grill, and two charming wooden rocking chairs on the covered back porch, where you can sit awhile, sip your sweet tea, and enjoy the sunset." }, { type: "p", text: "The Firefly Bungalow is a duplex with a privacy fence in between the two units. In addition to the fence, the property is nestled in a forested grove that provides natural privacy from the bustling parkway." }, { type: "p", text: "This cozy, rustic, casual, and comfortable bungalow is the ideal all-season getaway for travelers who appreciate the area’s natural splendor. Guests have described Firefly Bungalow #2 as “peaceful, romantic, relaxing, secluded, clean and calming.”  It is the perfect basecamp for all your Smoky Mountain adventures!" }, { type: "p", text: "About The Neighborhood:" }, { type: "p", text: "Firefly Bungalow #2 is private and secluded, yet convenient to the best of Gatlinburg, Pigeon Forge, Cherokee, NC, and the best of the Great Smoky Mountains National Park. Prime location, right off the Parkway (Route 441) is a highlight of this bungalow. Guests who value a walkable, downtown location will truly love Firefly Bungalows!" }, { type: "p", text: "This mountain cabin-style home boasts a combination of old-time charm and modern amenities. Enjoy wooden rocking chairs on the covered back porch, where you can savor melodies of birdsong and mountain breezes. Indulge in modern amenities such as Smart TVs, WiFi, a fully equipped kitchen, and a steaming hot tub beside the outdoor picnic area." }, { type: "p", text: "The Firefly Bungalow is a duplex with a privacy fence in between the two units. In addition to the fence, the property is nestled in a forested grove that provides a natural privacy screen.  A highlight of this property is its prime location just off the Parkway ( U.S. Route 441) in the heart of Pigeon Forge. Route 441 is the main route through the Great Smoky Mountains National Park to connect Gatlinburg, TN to Cherokee, NC." }, { type: "p", text: "Guests can easily stroll to Sunliner Diner, Dunkin Donuts, Cracker Barrel Country Store, the Hollywood Wax Museum, and the Trolley stop. There is so much to do right in Pigeon Forge! Dollywood and Dollywood Splash Country are major attractions. Check out MagiQuest Family Amusement Park, Pigeon Forge Gem Mine, Island Mirror Maze, TITANIC Museum, Hatfield and McCoy Dinner Show, Smoky Mountain Ziplines, Wonderworks, or Rainforest Adventures Zoo." }, { type: "p", text: "Explore downtown Gatlinburg! Ober Gatlinburg features a sky tram, skiing, mini-golf, wildlife encounters, and more.  Anakeesta is another popular outdoor adventure hub offering zip lining, gondola rides, a treetop play area, and more. Families love the Ripley’s Aquarium of the Smokies and the Gatlinburg Space Needle." }, { type: "p", text: "If hiking in the Great Smoky Mountains National Park is your plan, we recommend Chimney Tops Trail, Rainbow Falls Trail, Alum Cave Trail to Mount LeConte, and the Clingmans Dome Observation Tower Trail." }] } });
