  rows.push({ siteId: site.id, pageSlug: "firefly-bungalow-2", sectionKey: "amenities", order: 0, content: { groups: [{ name: "Setting & View", items: "City (Our Bunaglow is steps from the parkway, yet tucked away so you still have some privacy. There is a trolley stop nearby so you have access to the trolley routes while you leave your car parked at the bungalow. With such close access, keep in mind there may be some road noise from the parkway.), Downtown (Guests can easily stroll to Sunliner Diner, Dunkin Donuts, Cracker Barrel Country Store, the Hollywood Wax Museum, and the Trolley stop. There is so much to do right in Pigeon Forge! Dollywood and Dollywood Splash Country are major attractions. Check out MagiQuest Family Amusement Park, Pigeon Forge Gem Mine, Island Mirror Maze, TITANIC Museum, Hatfield and McCoy Dinner Show, Smoky Mountain Ziplines, Wonderworks or Rainforest Adventures Zoo.), Town (The Firefly Bungalow is a duplex with a privacy fence in between the two units. In addition to the fence, the property is nestled in a forested grove that provides a natural privacy screen. A highlight of this property is its prime location just off the Parkway (U.S. Route 441) in the heart of Pigeon Forge. Route 441 is the main route through the Great Smoky Mountains National Park to connect Gatlinburg, TN to Cherokee, NC.), City Skyline View (If hiking in the Great Smoky Mountains National Park is your plan, we recommend Chimney Tops Trail, Rainbow Falls Trail, Alum Cave Trail to Mount LeConte, and the Clingmans Dome Observation Tower Trail.)" }, { name: "General", items: "Internet / Wifi (Free), Fireplace (Electric Fireplace Indoors), Air Conditioning (This bungalow has a mini-split HVAC system), Linens Provided, Towels Provided, Hot Water, Hair Dryer, Ceiling Fans, Basic Soaps, Paper Towels, Shampoo, Toilet Paper, Hangers, Private Entrance, Lock On Bedroom Door, Hair Conditioner, Shower Gel, Clothing Storage (closet or wardrobe)" }, { name: "Kitchen", items: "Kitchen, Refrigerator, Stove, Oven, Microwave, Dishes & Utensils, Spices/Pantry Items, Coffee Maker, Toaster, Freezer, Pots & Pans, Dining Table, Baking Sheet, Barbeque/Grill Utensils, Wine Glasses" }, { name: "Entertainment", items: "Television, Stereo, Games/Board Games, Smart TV" }, { name: "Outdoor", items: "Outdoor Grill, Deck/Patio (uncovered), Balcony/Terrace, Lawn/Garden, Private Yard, Fire Pit, Outdoor Dining, Outdoor Seating" }, { name: "Pool/Spa", items: "Hot Tub" }, { name: "Family", items: "Pack N Play/Travel Crib (Our pack and play must be requested at least 24 hours prior to arrival.), Children's Books & Toys" }, { name: "Vehicles", items: "Free Parking (On Site, Free)" }, { name: "Safety", items: "Fire Extinguisher, Exterior Lighting, Smoke Detector, Cleaning Disinfection, Common Surface Disinfectant Cleaned, Cleaning Products" }, { name: "Accessibility", items: "Single Level Home, Home Step Free Access, Path To Entrance Lit At Night" }] } });
