  rows.push({ siteId: site.id, pageSlug: "firefly-bungalow-1", sectionKey: "basics", order: 0, content: { name: "Firefly Bungalow #1", tagline: "Steps From the Parkway", description: "An in-town Pigeon Forge home base with your own private hot tub and an exceptionally convenient location for exploring.", image: "https://admin.weblaucher.com/api/media/sites/6d8fcbd5-beb3-465d-9e55-d6da1ae3ef42/seed/stylish-bungalow.jpg", highlights: ["Private hot tub", "Steps from the Parkway", "String lights"], badgeLabel: "Remodeled", size: "1 Bedroom", baths: 1, sleeps: 3, categoryLabel: "Walk to the Parkway" } });
  rows.push({ siteId: site.id, pageSlug: "firefly-bungalow-1", sectionKey: "detail", order: 0, content: { headline: "Steps From the Pigeon Forge Parkway", subtitle: "In-town Pigeon Forge · Private hot tub · Convenient to attractions", story: ["Firefly Bungalow #1 is for travelers who would rather spend their vacation exploring than driving back and forth to town.", "Located steps from the Pigeon Forge Parkway on the side of the property closest to the mountains, it gives you an exceptionally convenient home base with your own private hot tub waiting when the day is done.", "Walk to nearby attractions and restaurants, explore Pigeon Forge, head into Gatlinburg or spend the day in Great Smoky Mountains National Park—then come back and unwind beneath the string lights.", "Because of its central in-town location, guests may occasionally hear normal road or town noise."], highlights: ["Steps From the Parkway", "Private Hot Tub", "In-Town Pigeon Forge Location", "Outdoor Space + String Lights", "Easy Access to Attractions & Restaurants"] } });
