  rows.push({ siteId: site.id, pageSlug: "firefly-bungalow-1", sectionKey: "photos", order: 0, content: { items: ["https://uc.orez.io/i/9229802c53944bebaed4f77e3d92b721-Large", "https://uc.orez.io/i/f79c2bad4e404a96a657bd3e77840a41-Large", "https://uc.orez.io/i/ae01b9e4959e415586cc3ed41f0b0d72-Large", "https://uc.orez.io/i/87dfb46fd0104fb1a57613bcbaecac4f-Large", "https://uc.orez.io/i/a336d44a0c6a4e0e9f83e33c648673e0-Large", "https://uc.orez.io/i/21cbb4fa9cfd47caa5f807b4039b159a-Large", "https://uc.orez.io/i/2724eb7449194dee97b76ef9d7307ed7-Large", "https://uc.orez.io/i/21815b5b08ed4461aa4e6f05c0e26f63-Large", "https://uc.orez.io/i/905408ba93e145909b015e6e8d6b9806-Large", "https://uc.orez.io/i/f5f3d2add1f647f88b49c6af7aab92b2-Large", "https://uc.orez.io/i/eff41a5b0b174dd38a4353e113deb972-Large", "https://uc.orez.io/i/9e3b8dc4c35c4634893e35b6739aed5d-Large", "https://uc.orez.io/i/a094117c40d64a63a4f650ea7a89866c-Large", "https://uc.orez.io/i/8155ac8f0d11494d845bdd9dead85ca1-Large", "https://uc.orez.io/i/9ea203885d6b4c8f97015901ce129b0a-Large", "https://uc.orez.io/i/1dab557266624f118e52aa2a13cc6eb2-Large", "https://uc.orez.io/i/27895909908d4036b7c3a3d96898c4e5-Large", "https://uc.orez.io/i/93ef1cb7774140ffa4d7e70c7899d827-Large", "https://uc.orez.io/i/7785f424b829423085a4763bf3a04e33-Large", "https://uc.orez.io/i/0161d8b5604a4892905123870ec76a03-Large", "https://uc.orez.io/i/13d92a08b2a14c41971fb8a9b11809d9-Large", "https://uc.orez.io/i/a33a81dd8ed144419518419598225dfe-Large", "https://uc.orez.io/i/574d774a4b4344df97057814a9b3e907-Large", "https://uc.orez.io/i/e50b74e0402a4bd29070d9f137b7899f-Large", "https://uc.orez.io/i/725b9ade63394fb489ed78bc0cfab2a3-Large", "https://uc.orez.io/i/cb2c6478c4164108ac9da375b6f213cd-Large", "https://uc.orez.io/i/8e5924756c94470ebba1d62c19230d31-Large", "https://uc.orez.io/i/58d7caf327d24ba0ad6e001e0bf804d1-Large", "https://uc.orez.io/i/b20370ecc0ee4065989f91b24d364f64-Large"] } });
  rows.push({ siteId: site.id, pageSlug: "firefly-bungalow-1", sectionKey: "description", order: 0, content: { blocks: [{ type: "p", text: "Here at Firefly Bungalow #1, the music of crickets, peepers, and whippoorwills will lull you to sleep. The faint fragrance of mountain magnolia will greet you in springtime. Flashes of fireflies, and rhythms of rain on the metal roof will delight you on summer evenings. Autumn foliage will lure the leaf peepers. Fresh winter snowfall on mountain peaks is breathtaking, and holiday events in the Smokies draw travelers from around the world. Firefly Bungalow #1 is perfect for couples and small families who enjoy being close to all the action and don’t mind the occasional road noise that accompanies it." }, { type: "h", text: "Living Spaces" }, { type: "p", text: "The living room has a mist-gray sofa bed, a coffee table, an electric fireplace, and a large wall-mounted flat-screen TV. After a day exploring the mountains, curl up in the evenings and stream your favorite movies or shows, or choose from a variety of family board games." }, { type: "p", text: "This freshly remodeled, bright and airy, one-story bungalow is tranquil in all seasons.  It has ductless heat/AC units for cooling in the summer and heating in winter. A combination of stylish, rustic-chic furnishings and old-time Appalachian decor give this cabin-style home a comfortable Smoky Mountain ambiance." }, { type: "h", text: "Kitchen & Dining" }, { type: "p", text: "The brand new kitchen has state-of-the-art, stainless steel appliances, including a French door fridge/freezer combo, a four-burner electric range, oven, microwave, dishwasher, Keurig coffee maker, toaster, and large double-basin stainless steel sink with retractable faucet. A gorgeous barnwood-style breakfast bar offers stool seating for three; the perfect spot to sip your morning coffee!  A natural wood, open shelf in the corner nicely displays dishware, glassware, and stemware." }, { type: "h", text: "Bedrooms & Baths" }, { type: "p", text: "A sliding barn door connects the living room and the bedroom.  The bedroom offers a luxurious king-size bed and authentic quilts with patterns of bears, bear prints, mountain peaks, and evergreen trees." }, { type: "p", text: "Matching live-edge, natural wood nightstands, and lantern-style reading lamps add Appalachian character to the bedroom. The bedroom also has a sleek, modern ceiling fan, tasteful and calming fine art, a small futon, and a work desk with chair. (For guests traveling with small children, a pack and play is also available upon request.)" }, { type: "p", text: "Sliding barn doors from the king bedroom lead to a stylish and sophisticated ensuite full bathroom with a spa-style Jacuzzi and a walk-in shower. This bathroom is also accessible from a sliding barn door off the kitchen/living room, where the sleeper sofa is located. The luxurious bathroom boasts rustic-chic wrought iron chandeliers, a large, full-length mirror, a single-sink granite vanity, and plenty of cabinet storage space. Toiletries, hairdryer, robes, and plush towels are all provided." }, { type: "h", text: "Outdoor Amenities" }, { type: "p", text: "The outdoor patio area truly sets this bungalow apart. Indulge in the hot tub after a day of Smoky Mountain adventure or gather around the fire pit for s’mores. The backyard offers a picnic table for outdoor dining, a BBQ grill, and lounge chairs where you can sit awhile, sip your sweet tea, and enjoy the sunset. The Firefly Bungalow is a duplex with a privacy fence in between the two units. In addition to the fence, the property is nestled in a forested grove that provides natural privacy" }, { type: "p", text: "Firefly Bungalow #1 is the ideal all-season getaway for travelers who appreciate the area’s natural splendor. Guests have described Firefly Bungalow #1 as “peaceful, romantic, relaxing, secluded, clean, stylish, trendy, sophisticated and calming.”  It is the perfect basecamp for all your Smoky Mountain adventures!" }, { type: "p", text: "About The Neighborhood:" }, { type: "p", text: "Firefly Bungalow #1 is private and secluded, yet convenient to the best of Gatlinburg, Pigeon Forge, Cherokee, NC,  and the best of the Great Smoky Mountains National Park. Prime location, right off the Parkway (Route 441) is a highlight of this bungalow. Guests who value a walkable, downtown location will truly love Firefly Bungalows!" }, { type: "p", text: "This mountain cabin-style home boasts a combination of old-time charm and stylish, modern amenities. Enjoy a backyard with a picnic area where you can savor melodies of birdsong and mountain breezes. Indulge in modern amenities such as Smart TVs, WiFi, a fully equipped kitchen, a spa-style bathroom with jacuzzi, and a steaming hot tub beside the outdoor picnic area." }, { type: "p", text: "The Firefly Bungalow is a duplex with a privacy fence in between the two units. In addition to the fence, the property is nestled in a forested grove that provides a natural privacy screen.  A highlight of this property is its prime location just off the Parkway ( U.S. Route 441) in the heart of Pigeon Forge. Route 441 is the main route through the Great Smoky Mountains National Park to connect Gatlinburg, TN to Cherokee, NC." }, { type: "p", text: "Guests can easily stroll to Sunliner Diner, Dunkin Donuts, Cracker Barrel Country Store, the Hollywood Wax Museum, and the Trolley stop. There is so much to do right in Pigeon Forge! Dollywood and Dollywood Splash Country are major attractions. Check out MagiQuest Family Amusement Park, Pigeon Forge Gem Mine, Island Mirror Maze, TITANIC Museum, Hatfield and McCoy Dinner Show, Smoky Mountain Ziplines, Wonderworks or Rainforest Adventures Zoo." }, { type: "p", text: "Explore downtown Gatlinburg! Ober Gatlinburg features a sky tram, skiing, mini-golf, wildlife encounters, and more.  Anakeesta is another popular outdoor adventure hub offering zip lining, gondola rides, a treetop play area, and more. Families love the Ripley’s Aquarium of the Smokies and the Gatlinburg Space Needle." }, { type: "p", text: "If hiking in the Great Smoky Mountains National Park is your plan, we recommend Chimney Tops Trail, Rainbow Falls Trail, Alum Cave Trail to Mount LeConte, and the Clingmans Dome Observation Tower Trail." }] } });
