  rows.push({ siteId: site.id, pageSlug: "home", sectionKey: "welcome", order: 0, content: { eyebrow: "Welcome to the Smokies", heading: "Romance, tucked into the trees", paragraph1: "No crowded resort. No shared hot tub. No rooms you don't need. Just your own cabin, your own deck and space to slow down.", paragraph2: "Our couples cabins are made for honeymoons, anniversaries, birthdays, spontaneous weekends—or simply a few days away together.", ratingLabel: "Average guest rating", reviewsLabel: "Happy guest reviews", thirdStatValue: "10 min", thirdStatLabel: "To Dollywood & the Parkway", badge: "Made for couples", image1: "https://admin.weblaucher.com/api/media/sites/6d8fcbd5-beb3-465d-9e55-d6da1ae3ef42/seed/emerald-forest.jpg", image2: "https://admin.weblaucher.com/api/media/sites/6d8fcbd5-beb3-465d-9e55-d6da1ae3ef42/seed/emerald-forest-interior.webp", primaryLabel: "Find Your Cabin", secondaryLabel: "Talk to your hosts" } });
  rows.push({ siteId: site.id, pageSlug: "home", sectionKey: "amenities", order: 0, content: { eyebrow: "Cabin comforts", heading: "The Comforts Our Guests Love", description: "Amenities vary by property. Explore each cabin to find the retreat that fits your trip.", items: [{ title: "Private Hot Tubs", text: "Your own hot tub on your own deck or patio, never shared." }, { title: "Fireside Double Jacuzzis", text: "Indoor double Jacuzzis, many set right beside the fire." }, { title: "King Beds", text: "Including premium Stearns & Foster mattresses in our Hidden Gems." }, { title: "Fireplaces", text: "Wood-burning, gas or electric, depending on the cabin." }, { title: "Kitchens", text: "Equipped for breakfast in pajamas or dinner for two." }, { title: "Forest Decks & Porches", text: "Wrap-around decks, porches and porch swings among the trees." }] } });
  rows.push({ siteId: site.id, pageSlug: "home", sectionKey: "twoWays", order: 0, content: { eyebrow: "Two ways to escape", heading: "Deep in the Woods. Close to It All.", buttonLabel: "See these cabins", description: "Spend the morning hiking in Great Smoky Mountains National Park, the afternoon exploring Gatlinburg, or the evening enjoying Pigeon Forge. Then come home to your own hot tub beneath the trees. Prefer to be in the middle of everything? Our Firefly Bungalows put you steps from the Pigeon Forge Parkway.", items: [{ image: "https://admin.weblaucher.com/api/media/sites/6d8fcbd5-beb3-465d-9e55-d6da1ae3ef42/seed/just-opened.jpg", eyebrow: "For two", title: "Secluded in the forest", points: "Hot tubs overlooking acres of trees, A-frames & rustic studio cabins, 5 mi to Gatlinburg & Pigeon Forge" }, { image: "https://admin.weblaucher.com/api/media/sites/6d8fcbd5-beb3-465d-9e55-d6da1ae3ef42/seed/steps-from-parkway.jpg", eyebrow: "For couples & small groups", title: "Steps from the Parkway", points: "Walk to shows, dining & trolley stops, Firepits, string lights & hot tubs, Bungalows sleeping up to 6" }] } });
  rows.push({ siteId: site.id, pageSlug: "home", sectionKey: "explore", order: 0, content: { eyebrow: "Explore the Smokies", heading: "Adventure by day, hot tub by night", description: "Our cabins sit right between the National Park and the heart of Pigeon Forge and Gatlinburg, so the best of the Smokies is a short drive (or stroll) away.", items: [{ name: "Great Smoky Mountains National Park", distance: "10 mi", description: "Misty ridgelines, waterfalls and 800+ miles of trails. Catch sunrise at Clingmans Dome or drive the Cades Cove loop.", image: "https://admin.weblaucher.com/api/media/sites/6d8fcbd5-beb3-465d-9e55-d6da1ae3ef42/seed/national-park.jpg", focus: "center" }, { name: "Downtown Gatlinburg", distance: "5–11 mi", description: "Stroll the lantern-lit Parkway for mountain crafts, moonshine tastings, cozy dinners and the SkyBridge.", image: "https://admin.weblaucher.com/api/media/sites/6d8fcbd5-beb3-465d-9e55-d6da1ae3ef42/seed/gatlinburg.jpg", focus: "center" }, { name: "Pigeon Forge Parkway", distance: "Steps away", description: "Dinner shows, museums, go-karts and trolley stops, right outside the door of our Parkway bungalows.", image: "https://admin.weblaucher.com/api/media/sites/6d8fcbd5-beb3-465d-9e55-d6da1ae3ef42/seed/pigeon-forge.jpeg", focus: "left center" }, { name: "Dollywood", distance: "5 mi", description: "Dolly Parton's award-winning theme park, home to roller coasters, Smoky Mountain music and seasonal festivals of lights.", image: "https://admin.weblaucher.com/api/media/sites/6d8fcbd5-beb3-465d-9e55-d6da1ae3ef42/seed/dollywood.jpg", focus: "center" }] } });
  rows.push({ siteId: site.id, pageSlug: "home", sectionKey: "finalCta", order: 0, content: { eyebrow: "Family-run in East Tennessee", heading: "Small Cabins. Big Memories.", description: "Vacay To The Smokies is a family-run East Tennessee cabin company built around a simple idea: A memorable mountain getaway doesn't have to be the biggest cabin on the mountain. It needs the right setting, thoughtful details and space to enjoy the people you came with.", primaryLabel: "Find Your Cabin", image: "https://admin.weblaucher.com/api/media/sites/6d8fcbd5-beb3-465d-9e55-d6da1ae3ef42/seed/stylish-bungalow.jpg" } });
  rows.push({ siteId: site.id, pageSlug: "home", sectionKey: "bookingDirect", order: 0, content: { eyebrow: "Good to know", heading: "Booking Direct?", description: "Reservations completed on this website are direct bookings with Vacay To The Smokies. Reservations made through Airbnb, Vrbo, Booking.com, Expedia or another platform are subject to the terms associated with that reservation.", checkInNote: "All guests, regardless of booking channel, must complete our secure online check-in before arrival.", guestServicesLabel: "Guest Services:", buttonLabel: "View Direct Booking Policies & Good to Know" } });
