  rows.push({ siteId: site.id, pageSlug: "policies", sectionKey: "cancellation", order: 0, content: { title: "Cancellation Policy", badge: "Direct bookings", p0: "For reservations booked directly with Vacay To The Smokies:", period1Label: "More than 30 days before arrival", period1Text: "Fifty percent (50%) of the total booking charges will be refunded.", period2Label: "30 days or less before arrival", period2Text: "No refund will be issued.", p1: "Cancellation policies for reservations made through Airbnb, Vrbo, Booking.com, Expedia, or another third-party platform may be different. Guests who booked through one of these platforms should refer to the cancellation policy associated with their reservation before requesting a cancellation." } });
  rows.push({ siteId: site.id, pageSlug: "policies", sectionKey: "checkInCheckout", order: 0, content: { title: "Check-In & Checkout", checkInTime: "4:00 PM", checkOutTime: "11:00 AM", p1: "Most cabins offer self check-in. Property access information, check-in instructions, and the exact property address are provided before arrival after completion of any required check-in and verification steps.", p2: "Guests who booked through a third-party platform should also review communications provided through that platform." } });
  rows.push({ siteId: site.id, pageSlug: "policies", sectionKey: "houseRules", order: 0, content: { title: "House Rules", intro: "Unless different or additional rules are specifically stated for your property or reservation:", bullets: ["No smoking, parties, or events.", "The primary renter must be at least 18 years old.", "Pets are welcome at designated pet-friendly properties with prior approval and payment of the applicable pet fee. Pets should be crated when left unattended.", "Maximum occupancy is stated for each property and may not be exceeded.", "Additional property-specific rules may apply and will be provided with your reservation."] } });
  rows.push({ siteId: site.id, pageSlug: "policies", sectionKey: "payments", order: 0, content: { title: "Payments", badge: "Direct bookings", p1: "For reservations booked directly with Vacay To The Smokies, Vacay To The Smokies is the merchant of record and charges associated with your reservation will be processed by Vacay To The Smokies.", p2: "Credit and debit card payments are securely processed through Authorize.net. Vacay To The Smokies does not store your full payment card number.", p3: "Prices displayed during direct booking checkout include the applicable rent, cleaning fee, approved pet fee, if any, and lodging taxes.", p4: "Reservations made through Airbnb, Vrbo, Booking.com, Expedia, or another third-party booking platform may have different payment schedules, fees, payment-processing arrangements, and terms. Please refer to the payment information associated with the platform through which you booked." } });
  rows.push({ siteId: site.id, pageSlug: "policies", sectionKey: "privacy", order: 0, content: { title: "Privacy", p1: "For direct reservations, the information you provide during booking and online check-in—including your name, email address, phone number, reservation information, identification and other required verification information—is used to manage and verify your reservation, facilitate check-in, provide your stay, and communicate with you regarding your booking.", p2: "Payment card information is securely processed through Authorize.net.", p3: "Guests who book through a third-party platform are also subject to that platform's privacy policy and data-handling practices." } });

