  rows.push({ siteId: site.id, pageSlug: "hidden-gems", sectionKey: "intro", order: 0, content: { eyebrow: "Hidden Gem Cabin Series", heading: "Four Gemstones. Four Cabins. Each Created for Two.", description: "Tucked into the Smoky Mountain forest between Gatlinburg and Pigeon Forge, our Hidden Gem Cabin Series takes one intimate couples-focused concept and gives each cabin a personality of its own.", footnote: "And just enough space for two.", closing: "Our Hidden Gems give you the feeling of disappearing into the forest while keeping Gatlinburg, Pigeon Forge and Great Smoky Mountains National Park within easy reach.", items: [{ gem: "EMERALD", theme: "Forest & Nature", name: "Emerald Forest", long: "Deep greens, forest views and the cabin where our Hidden Gem story began." }, { gem: "GOLDEN", theme: "Warmth & Glow", name: "Golden Forest", long: "Golden details, warm finishes and changing light through the forest." }, { gem: "JADE", theme: "Wellness & Spa", name: "Jade Forest", long: "Your own private spa in the Smokies, with a sauna, cold plunge, vitamin C shower, hot tub and fireside double Jacuzzi, surrounded by jade and natural earth tones." }, { gem: "DIAMOND", theme: "Light & Contrast", name: "Diamond Forest", long: "A cooler, lighter personality with soft whites and greys contrasted against authentic log walls." }] } });

  rows.push({ siteId: site.id, pageSlug: "jade-forest", sectionKey: "comingSoon", order: 0, content: { title: "Jade Forest — Coming Soon", headline: "Your Private Spa in the Smokies", paragraphs: ["The third cabin in our Hidden Gem Series is being created around an entirely new experience: wellness in the woods.", "Jade Forest will pair the warmth of an intimate Smoky Mountain cabin with the restorative feeling of a private spa retreat—all designed exclusively for two. Rich jade and natural earth tones will flow throughout the cabin, connecting the interior to the forest just outside."], featuresLabel: "Planned highlights", features: [{ item: "Private Sauna" }, { item: "Cold Plunge" }, { item: "Vitamin C Shower" }, { item: "Private Hot Tub" }, { item: "Fireside Double Jacuzzi" }, { item: "King Stearns & Foster Bed" }, { item: "Full Kitchen" }, { item: "Fireplace" }, { item: "Wrap-Around Deck" }], status: "Jade Forest is currently under construction and is not yet accepting reservations." } });

