  rows.push({ siteId: site.id, pageSlug: "global", sectionKey: "footer", order: 0, content: { tagline: "Romantic cabins with private hot tubs, tucked between Gatlinburg and Pigeon Forge, Tennessee.", copyrightNote: "All rights reserved." } });
